mapper.select:


    and q.del_flag = '0'
    and q.subject_id = #{subjectId}
    and q.question_type = #{questionType}
    and q.difficulty = #{difficulty}
    and q.status = #{status}
    and q.question_code like concat('%', #{questionCode}, '%')
    and q.content like concat('%', #{content}, '%')

        and not exists (select 1 from spas_qb_question_knowledge qk2 where qk2.question_id = q.question_id)


        and exists (select 1 from spas_qb_question_knowledge qk3 where qk3.question_id = q.question_id)


        and exists (
            select 1 from spas_qb_question_knowledge qk
            where qk.question_id = q.question_id and qk.knowledge_id = #{knowledgeId}
        )


        and exists (
            select 1 from spas_qb_question_knowledge qk
            where qk.question_id = q.question_id
              and qk.knowledge_id in
              #{kid}
        )


        and exists (
            select 1 from spas_qb_question_knowledge qk
            inner join spas_knowledge k on k.knowledge_id = qk.knowledge_id
            where qk.question_id = q.question_id
              and (
                qk.knowledge_id = #{chapterId}
                or cast(#{chapterId} as varchar) = any(string_to_array(k.ancestors, ','))
              )
        )

    and q.source_year = #{sourceYear}
    and q.source_region like concat('%', #{sourceRegion}, '%')
    and q.source_exam like concat('%', #{sourceExam}, '%')

order by q.question_id desc

mapper.update:
update spas_qb_question
question_code = #{questionCode}, content = #{content}, options = #{options}, correct_answer = #{correctAnswer}, subject_id = #{subjectId}, question_type = #{questionType}, difficulty = #{difficulty}, analysis = #{analysis}, content_hash = #{contentHash}, stem_image = #{stemImage}, options_image = #{optionsImage}, answer_image = #{answerImage}, analysis_image = #{analysisImage}, source_year = #{sourceYear}, source_region = #{sourceRegion}, source_exam = #{sourceExam}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where question_id = #{questionId}

update spas_qb_question set del_flag = '2', update_time = now()
where question_id in
#{id}
